document.querySelectorAll('[data-lab="G01-I1"]').forEach(root => { if(root.dataset.ready) return; root.dataset.ready='true'; const count=root.querySelector('[data-count]'), length=root.querySelector('[data-length]'), zh=root.dataset.lang==='zh'; function update(){const n=Number(count.value), l=Number(length.value), volume=l*l*l, rho=n*0.01801528/(6.02214076e23*volume*1e-27);root.querySelector('[data-count-output]').textContent=String(n);root.querySelector('[data-length-output]').textContent=l.toFixed(2)+' nm';root.querySelector('[data-density]').textContent=rho.toFixed(2)+' kg/m³';root.querySelector('[data-volume]').textContent=(zh?'体积：':'Volume: ')+volume.toFixed(3)+' nm³';const s=l*65,box=root.querySelector('[data-box]');box.setAttribute('x',155-s/2);box.setAttribute('y',165-s/2);box.setAttribute('width',s);box.setAttribute('height',s);root.querySelector('[data-explanation]').textContent=zh?'这 '+n+' 个水分子的总质量保持由分子数决定；当前边长为 '+l.toFixed(2)+' nm。固定分子数时，边长增大使体积按三次方增大，密度随之下降。':'For '+n+' water molecules, the total mass follows the molecule count. The side length is '+l.toFixed(2)+' nm. At fixed count, volume grows with the cube of side length and density falls.';} count.addEventListener('input',update);length.addEventListener('input',update);root.querySelector('[data-reset]').addEventListener('click',()=>{count.value='900';length.value='3';update();});update();});